using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using EfFixtures;
using Microsoft.EntityFrameworkCore;

public record PostSummary(int Id, string Title);

public static class PostQueries
{
    public static async Task<List<PostSummary>> GetPostsByTitlePrefixAsync(
        BlogContext blogContext,
        string prefix,
        CancellationToken cancellationToken)
    {
        var postSummaryQuery =
            from post in blogContext.Posts
            select new PostSummary(post.Id, post.Title);

        var postSummaries = await postSummaryQuery.ToListAsync(cancellationToken);

        // TitleRules.HasPrefix is a C# helper that EF Core cannot translate to SQL,
        // so the prefix filter is applied after the projected titles are loaded.
        return postSummaries
            .Where(postSummary => TitleRules.HasPrefix(postSummary.Title, prefix))
            .ToList();
    }
