{
    public string Title { get; set; }
    public int Views { get; set; }
}

public static class PostQueries
{
    public static async Task<List<PostTitleAndViews>> GetPopularPostsAsync(BlogContext blogContext, CancellationToken cancellationToken)
    {
        var popularPostsQuery = blogContext.Posts
            .Where(post => post.Views > 100)
            .OrderByDescending(post => post.Views)
            .Select(post => new PostTitleAndViews
            {
                Title = post.Title,
